/**
 * Build the server-side render bundle used by the publish-time bake.
 *
 * Runs after `vite build`, because it captures dist/index.html — the built shell,
 * with its hashed asset tags — as a string. Capturing the shell at build time (as
 * opposed to self-fetching it over HTTP at request time) keeps a baked page's
 * asset URLs guaranteed consistent with the deployment that baked it.
 *
 * Both outputs are underscore-prefixed so Vercel treats them as private helpers
 * rather than routable functions, the same way api/_club.js already works.
 */
import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const R = (p) => resolve(root, p);

// react-dom/server is CommonJS and dynamically require()s node builtins, which an
// ESM bundle has no `require` for. This banner gives the bundle one.
const ESM_REQUIRE_BANNER =
  'import{createRequire as __cr}from"module";const require=__cr(import.meta.url);';

async function bundleRenderer() {
  await build({
    entryPoints: [R("src/lib/ssrEntry.ts")],
    outfile: R("api/_ssr.mjs"),
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node18",
    jsx: "automatic",
    banner: { js: ESM_REQUIRE_BANNER },
    // The public tree imports styles and images for the browser build; the server
    // render only produces markup, so they resolve to nothing here.
    loader: {
      ".css": "empty",
      ".svg": "empty",
      ".png": "empty",
      ".jpg": "empty",
      ".jpeg": "empty",
      ".webp": "empty",
      ".gif": "empty",
      ".woff": "empty",
      ".woff2": "empty",
    },
    // Vite's import.meta.env doesn't exist under Node. The app's Supabase module
    // falls back to the public project + publishable key when these are unset, so
    // the bundle works without build-time secrets — and must: the publishable key
    // is RLS-scoped, and the bake deliberately reads as the public would.
    define: {
      "import.meta.env": JSON.stringify({
        DEV: false,
        PROD: true,
        MODE: "production",
        VITE_SUPABASE_URL: process.env.VITE_SUPABASE_URL ?? undefined,
        VITE_SUPABASE_ANON_KEY: process.env.VITE_SUPABASE_ANON_KEY ?? undefined,
      }),
    },
    logLevel: "warning",
  });
}

async function captureShell() {
  const shell = await readFile(R("dist/index.html"), "utf8");
  if (!shell.includes('id="root"')) {
    throw new Error('dist/index.html has no id="root" — the bake has nowhere to inject markup');
  }
  await writeFile(
    R("api/_shell.mjs"),
    `// GENERATED by scripts/build-ssr-bundle.mjs — do not edit.\n` +
      `export const SHELL_HTML = ${JSON.stringify(shell)};\n`,
    "utf8"
  );
  return shell.length;
}

const [, shellBytes] = await Promise.all([bundleRenderer(), captureShell()]);
console.log(`ssr bundle -> api/_ssr.mjs`);
console.log(`shell      -> api/_shell.mjs (${shellBytes} bytes captured from dist/index.html)`);
